SELECT migrazione, count(*) AS controlli_totali,
 count(*) FILTER (WHERE NOT ok) AS controlli_non_superati,
 COALESCE(jsonb_agg(controllo ORDER BY controllo) FILTER (WHERE NOT ok), '[]'::jsonb) AS da_verificare
FROM controlli GROUP BY migrazione ORDER BY migrazione;
